<?php
session_start();
if(!isset($_SESSION['id'],$_SESSION['role'])||!in_array($_SESSION['role'],['student','faculty'],true)){header('Location:dashboard.php');exit;}
include 'db.php'; $uid=(int)$_SESSION['id']; $role=$_SESSION['role'];
$s=$conn->prepare("SELECT b.id AS loan_id,b.issued_at,b.due_date,b.returned_at,b.status,k.book_name,k.author,k.category FROM borrowings b JOIN books k ON k.id=b.book_id WHERE b.member_id=? ORDER BY b.id DESC");
$s->bind_param('i',$uid);$s->execute();$result=$s->get_result();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>My Books | BookNest</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><header class="topbar"><a class="top-brand" href="dashboard.php">📚 BookNest <small>Library</small></a><div class="user-chip"><?= $role==='student'?'🎓':'👨‍🏫' ?> <?=htmlspecialchars($_SESSION['name'])?><span class="role-pill"><?=ucfirst($role)?></span></div></header><main class="page-content"><div class="page-head"><div><div class="eyebrow">MY LIBRARY</div><h1>📚 My Borrowed Books</h1><p><?=$role==='faculty'?'Faculty loans have a 30-day period and a 5-book active limit.':'Student loans have a 14-day period and a 3-book active limit.'?></p></div><div class="head-actions"><a class="secondary-btn" href="dashboard.php">🏠 Dashboard</a><a class="primary-small" href="view_books.php">📖 Browse Books</a></div></div><?php if(isset($_GET['success'])): ?><div class="alert success">✅ <?= $_GET['success']==='borrowed'?'Book borrowed successfully.':'Book returned successfully.' ?></div><?php elseif(isset($_GET['error'])): ?><div class="alert error">❌ <?= $_GET['error']==='already'?'You already have this book issued.':'Unable to complete that action.' ?></div><?php endif; ?><div class="table-card"><div class="table-wrap"><table><thead><tr><th>Book</th><th>Author</th><th>Category</th><th>Issued</th><th>Due Date</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if($result->num_rows===0): ?><tr><td colspan="7" class="empty">You have no borrowing records yet.</td></tr><?php else: while($r=$result->fetch_assoc()): $overdue=$r['status']==='issued' && $r['due_date'] && strtotime($r['due_date'])<time(); ?><tr><td><strong><?=htmlspecialchars($r['book_name'])?></strong></td><td><?=htmlspecialchars($r['author'])?></td><td><span class="category-tag"><?=htmlspecialchars($r['category'])?></span></td><td><?=date('d M Y',strtotime($r['issued_at']))?></td><td><?= $r['due_date'] ? date('d M Y',strtotime($r['due_date'])) : '—' ?><?php if($overdue): ?> <span class="overdue-tag">Overdue</span><?php endif; ?></td><td><span class="status-<?=htmlspecialchars($r['status'])?>"><?=ucfirst($r['status'])?></span></td><td><?php if($r['status']==='issued'): ?><a class="return-btn" href="return_book.php?id=<?=(int)$r['loan_id']?>" onclick="return confirm('Return this book?')">Return</a><?php else: ?><?= $r['returned_at'] ? date('d M Y',strtotime($r['returned_at'])) : 'Returned' ?><?php endif; ?></td></tr><?php endwhile; endif; ?></tbody></table></div></div></main></body></html>
